package org.dromara.ai.workspace;
import lombok.RequiredArgsConstructor;
import org.dromara.common.json.utils.JsonUtils;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.web.multipart.MultipartFile;
import java.util.*;
@Service
@RequiredArgsConstructor
public class WorkspaceKnowledge {
 private final JdbcTemplate jdbc;private final TransactionTemplate tx;private final WorkspaceKnowledgeAccess access;private final WorkspaceFileStore files;private final AiResourceGuard guard;private final WorkspaceConversations conversations;private final WorkspaceEvents events;
 public Map<String,Object> upload(UUID base,UUID document,Integer expected,UUID key,long user,MultipartFile file){access.base(base,user,AiResourceGuard.Action.EDIT);String name=WorkspaceFileStore.filename(file);byte[] bytes=WorkspaceFileStore.upload(file,2*1024*1024);String text=WorkspaceFileStore.text(name,bytes);if(text.length()>500000)throw new WorkspaceDenied(413,"DocumentTextLimitExceeded");return tx.execute(status->{jdbc.queryForObject("SELECT user_id FROM sys_user WHERE user_id=? FOR UPDATE",Long.class,user);String digest=WorkspaceTools.hash(base+":"+document+":"+expected+":"+name+":"+WorkspaceFileStore.hash(bytes));var old=jdbc.queryForList("SELECT input_hash,result::text FROM ai_command WHERE actor_user_id=? AND operation='knowledge.upload' AND idempotency_key=?",user,key);if(!old.isEmpty()){if(!digest.equals(old.getFirst().get("input_hash")))throw new WorkspaceDenied(409,"IdempotencyConflict");return JsonUtils.parseMap(old.getFirst().get("result").toString());}if(jdbc.queryForObject("SELECT COALESCE(sum(byte_size),0) FROM ai_file WHERE owner_user_id=? AND deleted_at IS NULL",Long.class,user)+bytes.length>50L*1024*1024)throw new WorkspaceDenied(413,"StorageQuotaExceeded");access.base(base,user,AiResourceGuard.Action.EDIT);
  UUID id=document==null?UUID.randomUUID():document;int version=1;if(document==null){if(jdbc.queryForObject("SELECT count(*) FROM ai_knowledge_document WHERE base_id=? AND deleted_at IS NULL",Integer.class,base)>=50)throw new WorkspaceDenied(409,"KnowledgeDocumentLimit");jdbc.update("INSERT INTO ai_knowledge_document(id,base_id,title,created_by) VALUES(?,?,?,?)",id,base,name,user);}else{jdbc.queryForList("SELECT id FROM ai_knowledge_document WHERE id=? FOR UPDATE",id);var doc=access.document(id,user,AiResourceGuard.Action.EDIT);if(!doc.get("base_id").equals(base)||expected==null||((Number)doc.get("latest_version")).intValue()!=expected)throw new WorkspaceDenied(409,"VersionConflict");version=expected+1;jdbc.update("UPDATE ai_knowledge_document SET latest_version=?,title=?,updated_at=NOW() WHERE id=?",version,name,id);}
  UUID fileId=files.save(user,"KNOWLEDGE",base,null,name,"text/plain; charset=utf-8",bytes),job=UUID.randomUUID();jdbc.update("INSERT INTO ai_knowledge_document_version(document_id,version,file_id,text_content,content_hash) VALUES(?,?,?,?,?)",id,version,fileId,text,WorkspaceTools.hash(text));jdbc.update("INSERT INTO ai_knowledge_job(id,document_id,version,requested_by) VALUES(?,?,?,?)",job,id,version,user);var result=Map.<String,Object>of("id",id.toString(),"version",version,"fileId",fileId.toString(),"jobId",job.toString(),"status","QUEUED");jdbc.update("INSERT INTO ai_command(actor_user_id,operation,idempotency_key,input_hash,result) VALUES(?,'knowledge.upload',?,?,?::jsonb)",user,key,digest,JsonUtils.toJsonString(result));audit(user,"knowledge.document.uploaded",base,Map.of("documentId",id.toString(),"version",version));return result;
 });}
 public List<Map<String,Object>> documents(UUID base,long user,int page){access.base(base,user,AiResourceGuard.Action.VIEW);boolean edit;try{access.base(base,user,AiResourceGuard.Action.EDIT);edit=true;}catch(WorkspaceDenied e){edit=false;}return jdbc.queryForList("SELECT d.id::text,f.filename AS title,d.latest_version,d.indexed_version,v.version,v.status,v.file_id::text,d.updated_at::text FROM ai_knowledge_document d JOIN ai_knowledge_document_version v ON v.document_id=d.id AND v.version=CASE WHEN ? THEN d.latest_version ELSE CASE WHEN ? THEN (SELECT version FROM ai_public_document p WHERE p.resource_id=d.base_id AND p.document_id=d.id) ELSE d.indexed_version END END JOIN ai_file f ON f.id=v.file_id WHERE d.base_id=? AND d.deleted_at IS NULL ORDER BY d.updated_at DESC LIMIT 30 OFFSET ?",edit,access.publicOnly(base,user,AiResourceGuard.Action.VIEW),base,(Math.max(1,Math.min(page,1000))-1)*30);}
 public void remove(UUID document,long user){tx.executeWithoutResult(status->{jdbc.queryForList("SELECT id FROM ai_knowledge_document WHERE id=? FOR UPDATE",document);var d=access.document(document,user,AiResourceGuard.Action.DELETE);jdbc.update("UPDATE ai_knowledge_document SET deleted_at=NOW(),auth_version=auth_version+1 WHERE id=?",document);jdbc.update("UPDATE ai_file SET deleted_at=NOW(),auth_version=auth_version+1 WHERE id IN(SELECT file_id FROM ai_knowledge_document_version WHERE document_id=?)",document);jdbc.update("UPDATE ai_knowledge_job SET status='CANCELLED',finished_at=NOW() WHERE document_id=? AND status IN('QUEUED','RUNNING')",document);audit(user,"knowledge.document.deleted",(UUID)d.get("base_id"),Map.of("documentId",document.toString()));});conversations.revokeDocument(document);}
 public Map<String,Object> reindex(UUID document,long user){return tx.execute(status->{jdbc.queryForList("SELECT id FROM ai_knowledge_document WHERE id=? FOR UPDATE",document);var d=access.document(document,user,AiResourceGuard.Action.EDIT);var active=jdbc.queryForList("SELECT id FROM ai_knowledge_job WHERE document_id=? AND version=? AND status IN('QUEUED','RUNNING')",document,d.get("latest_version"));if(!active.isEmpty())return Map.of("jobId",active.getFirst().get("id").toString(),"reused",true);UUID id=UUID.randomUUID();jdbc.update("INSERT INTO ai_knowledge_job(id,document_id,version,requested_by) VALUES(?,?,?,?)",id,document,d.get("latest_version"),user);return Map.of("jobId",id.toString(),"reused",false);});}
 public List<Map<String,Object>> jobs(UUID base,long user){access.base(base,user,AiResourceGuard.Action.VIEW);if(access.publicOnly(base,user,AiResourceGuard.Action.VIEW))return List.of();return jdbc.queryForList("SELECT j.id::text,j.document_id::text,j.version,j.status,j.error_code,j.created_at::text,j.finished_at::text FROM ai_knowledge_job j JOIN ai_knowledge_document d ON d.id=j.document_id WHERE d.base_id=? AND d.deleted_at IS NULL ORDER BY j.created_at DESC LIMIT 30",base);}
 private List<Map<String,Object>> matches(UUID base,UUID run,String query,boolean publicOnly){if(query==null||query.isBlank()||query.length()>200)throw new WorkspaceDenied(400,"InvalidKnowledgeQuery");List<String> terms=Arrays.stream(query.trim().split("[\\s，,。；;]+",8)).filter(s->!s.isBlank()).limit(8).toList();List<Object> args=new ArrayList<>();String source;if(run!=null){source="JOIN ai_run_document p ON p.document_id=i.document_id AND p.version=i.version WHERE p.run_id=?";args.add(run);}else{source="WHERE d.base_id=? AND i.version="+(publicOnly?"(SELECT version FROM ai_public_document p WHERE p.resource_id=d.base_id AND p.document_id=d.id)":"d.indexed_version");args.add(base);}String predicates=String.join(" OR ",Collections.nCopies(terms.size(),"i.content ILIKE ? ESCAPE '!'"));for(String t:terms)args.add("%"+t.replace("!","!!").replace("%","!%").replace("_","!_")+"%");args.add(query);return jdbc.queryForList("SELECT i.document_id::text,i.version,i.chunk_index,i.line_start,i.line_end,i.content,f.filename AS title,v.file_id::text FROM ai_knowledge_index i JOIN ai_knowledge_document d ON d.id=i.document_id JOIN ai_knowledge_document_version v ON v.document_id=i.document_id AND v.version=i.version JOIN ai_file f ON f.id=v.file_id "+source+" AND d.deleted_at IS NULL AND ("+predicates+") ORDER BY similarity(i.content,?) DESC,i.document_id,i.chunk_index LIMIT 5",args.toArray());}
 public List<Map<String,Object>> search(UUID base,long user,String query){access.base(base,user,AiResourceGuard.Action.USE);var result=matches(base,null,query,access.publicOnly(base,user,AiResourceGuard.Action.USE));access.base(base,user,AiResourceGuard.Action.USE);audit(user,"knowledge.search",base,Map.of("resultCount",result.size()));return result;}
 public Map<String,Object> retrieve(String grant,String query){return tx.execute(status->{var run=conversations.checkGrant(grant,true);UUID id=(UUID)run.get("id");jdbc.queryForObject("SELECT id FROM ai_run WHERE id=? FOR UPDATE",UUID.class,id);if(!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM ai_run_document WHERE run_id=?)",Boolean.class,id)))throw new WorkspaceDenied(403,"KnowledgeNotSelected");var results=matches(null,id,query,false);List<Map<String,Object>> citations=new ArrayList<>();for(var row:results){UUID doc=UUID.fromString(row.get("document_id").toString());int version=((Number)row.get("version")).intValue(),chunk=((Number)row.get("chunk_index")).intValue();var previous=jdbc.queryForList("SELECT id,reference FROM ai_knowledge_citation WHERE run_id=? AND document_id=? AND version=? AND chunk_index=?",id,doc,version,chunk);UUID citation=previous.isEmpty()?UUID.randomUUID():(UUID)previous.getFirst().get("id");String reference=previous.isEmpty()?"K"+(jdbc.queryForObject("SELECT count(*) FROM ai_knowledge_citation WHERE run_id=?",Integer.class,id)+1):previous.getFirst().get("reference").toString();if(previous.isEmpty())jdbc.update("INSERT INTO ai_knowledge_citation(id,run_id,document_id,version,chunk_index,reference) VALUES(?,?,?,?,?,?)",citation,id,doc,version,chunk,reference);Map<String,Object> c=new LinkedHashMap<>(row);c.put("id",citation.toString());c.put("reference",reference);citations.add(c);}conversations.checkGrant(grant,true);events.append((UUID)run.get("session_id"),id,UUID.randomUUID(),"knowledge.retrieved",Map.of("citations",citations));audit(((Number)run.get("owner_user_id")).longValue(),"knowledge.retrieved",null,Map.of("runId",id.toString(),"resultCount",citations.size()));return Map.of("citations",citations,"retrievalMode","LEXICAL_TEXT","instruction","仅依据返回原文回答，用 [K1] 等引用编号；无匹配时明确说明未找到，不猜测。");});}
 public Map<String,Object> citation(UUID id,WorkspacePrincipal.Actor actor){var rows=jdbc.queryForList("SELECT c.*,r.session_id FROM ai_knowledge_citation c JOIN ai_run r ON r.id=c.run_id WHERE c.id=? AND r.owner_user_id=?",id,actor.userId());if(rows.size()!=1)throw new WorkspaceDenied(404,"CitationNotFound");var c=rows.getFirst();conversations.authorizeSession((UUID)c.get("session_id"),actor);return preview((UUID)c.get("document_id"),((Number)c.get("version")).intValue(),actor.userId());}
 public Map<String,Object> preview(UUID document,int version,long user){var v=access.version(document,version,user,AiResourceGuard.Action.VIEW);var f=access.file((UUID)v.get("file_id"),user);audit(user,"knowledge.document.previewed",(UUID)f.get("resource_id"),Map.of("documentId",document.toString(),"version",version));return Map.of("documentId",document.toString(),"version",version,"filename",f.get("filename"),"content",v.get("text_content"),"fileId",f.get("id").toString(),"sha256",f.get("sha256"));}
 private void audit(long user,String action,UUID resource,Map<String,Object> metadata){jdbc.update("INSERT INTO ai_security_event(id,actor_user_id,action,resource_id,metadata) VALUES(?,?,?,?,?::jsonb)",UUID.randomUUID(),user,action,resource,JsonUtils.toJsonString(metadata));}
}
